```js
require('dotenv').config();
const express = require('express');
const helmet  = require('helmet');
const morgan  = require('morgan');
const jwt     = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');
const { param, validationResult } = require('express-validator');

const app = express();

// ── Security Middleware ──────────────────────────────────────────────────────
app.use(helmet());                            // Secure HTTP headers
app.use(morgan('combined'));                  // Request logging
app.use(express.json({ limit: '10kb' }));    // Body parsing with size limit
app.use(express.urlencoded({ extended: false }));

const limiter = rateLimit({                  // Rate limiting
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Enforce HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.headers['x-forwarded-proto'] !== 'https')
      return res.redirect(301, `https://${req.headers.host}${req.url}`);
    next();
  });
}

// ── Auth Middleware ──────────────────────────────────────────────────────────
function authenticateToken(req, res, next) {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Access token required' });
  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid or expired token' });
    req.user = user;
    next();
  });
}

// ── Routes ───────────────────────────────────────────────────────────────────
app.get('/health', (req, res) => {           // Public — no sensitive data
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticateToken, (req, res) => {  // Auth required
  console.log(`[AUDIT] User ${req.user.id} accessed /users at ${new Date().toISOString()}`);
  res.json([                                 // No emails in list response
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob'   },
  ]);
});

app.get('/users/:id',
  authenticateToken,
  param('id').isInt({ min: 1 }),             // Input validation
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const userId = parseInt(req.params.id, 10);
    // db.query('SELECT id, name FROM users WHERE id = $1', [userId])
    res.json({ id: userId, name: 'Alice' });
  }
);

// ── Global Error Handler ─────────────────────────────────────────────────────
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Internal server error' });
});

// ── Start ────────────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

module.exports = app;
```

