'use strict';

/**
 * app.js — Security-hardened Express application
 *
 * Fixes applied:
 *  1. HTTP security headers via helmet
 *  2. Rate limiting to prevent brute-force / DoS
 *  3. Authentication middleware on all sensitive routes
 *  4. Input validation with zod on parameterised routes
 *  5. JSON body size cap to prevent payload-bomb attacks
 *  6. PII field filtering on /users response
 *  7. Port read from environment variable
 *  8. Centralised error handler (no stack-trace leakage to client)
 */

const express = require('express');
const helmet  = require('helmet');
const rateLimit = require('express-rate-limit');
const { z } = require('zod');

const app = express();

// ─── 1. Security Headers ────────────────────────────────────────────────────
// Sets X-Content-Type-Options, X-Frame-Options, HSTS, CSP, and more.
app.use(helmet());

// ─── 2. Rate Limiting ────────────────────────────────────────────────────────
// 100 requests per 15 minutes per IP address.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ─── 3. Body Parser (size-limited) ──────────────────────────────────────────
// Reject payloads over 10 kb to prevent payload-bomb / memory exhaustion.
app.use(express.json({ limit: '10kb' }));

// ─── 4. Authentication Middleware ────────────────────────────────────────────
// Replace the simple token check with a proper JWT library (e.g. jsonwebtoken)
// in a production application: jwt.verify(token, process.env.JWT_SECRET)
function authenticate(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Expect: Bearer <token>

  if (!token) {
    return res.status(401).json({ error: 'Missing authorization token.' });
  }

  if (!process.env.API_TOKEN || token !== process.env.API_TOKEN) {
    return res.status(403).json({ error: 'Invalid or expired token.' });
  }

  next();
}

// ─── Mock data (replace with DB queries in production) ──────────────────────
// NOTE: In a real app, never store PII in source code. Use a database.
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
  { id: 2, name: 'Bob',   email: 'bob@example.com',   role: 'admin' },
];

// ─── Input validation schema ─────────────────────────────────────────────────
const UserQuerySchema = z.object({
  page:  z.coerce.number().int().min(1).max(1000).optional().default(1),
  limit: z.coerce.number().int().min(1).max(100).optional().default(20),
});

// ─── Routes ──────────────────────────────────────────────────────────────────

// Health check — intentionally public, returns no sensitive data
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list — protected + validated + PII-filtered
app.get('/users', authenticate, (req, res) => {
  // Validate and sanitise query parameters
  const parsed = UserQuerySchema.safeParse(req.query);
  if (!parsed.success) {
    return res.status(400).json({
      error: 'Invalid query parameters.',
      details: parsed.error.flatten(),
    });
  }

  const { page, limit } = parsed.data;
  const start = (page - 1) * limit;
  const end   = start + limit;

  // Strip sensitive fields (email, role) before sending to client.
  // Expose only what the consumer strictly needs.
  const safeUsers = USERS.slice(start, end).map(({ id, name }) => ({ id, name }));

  res.json({ page, limit, total: USERS.length, data: safeUsers });
});

// ─── 5. Centralised Error Handler ────────────────────────────────────────────
// Catches any error passed to next(err). Never leaks stack traces to clients.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  // Log the full error server-side (use a structured logger like pino/winston)
  console.error({ msg: 'Unhandled error', error: err.message, stack: err.stack });

  // Return a generic message — no internal details exposed
  res.status(500).json({ error: 'An unexpected error occurred.' });
});

// ─── Server ──────────────────────────────────────────────────────────────────
const PORT = parseInt(process.env.PORT, 10) || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

