The `.env.test` file sits in the project root alongside `app.js` with no `.gitignore` protection. Any `git push` would expose all secrets.

**Fix — `.gitignore`:**
```
# .gitignore
.env
.env.*
*.env
```

**Fix — Load secrets safely in code:**
```js
// Use dotenv only in non-production; never hard-code or log secrets
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config();
}
```

---

### 🔴 2. No Authentication or Authorization (Critical)
**OWASP A07 – Identification and Authentication Failures**

`GET /users` is completely open — any anonymous caller receives all user data. There is no auth middleware of any kind.

**Fix — JWT authentication middleware:**
```js
const jwt = require('jsonwebtoken');

function authenticate(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header' });
  }

  const token = authHeader.split(' ')[1];
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// Apply to sensitive routes:
app.get('/users', authenticate, (req, res) => { ... });
```

---

### 🟠 3. Sensitive Data Hardcoded in Source (High)
**OWASP A02 – Sensitive Data Exposure**

Real email addresses are embedded directly in source code. In production this would be database records, but even in dev/staging, hardcoded PII leaks into version history and logs.

**Before (vulnerable):**
```js
res.json([
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
]);
```

**Fix — externalise data and mask PII in responses:**
```js
// Fetch from DB; only return fields the caller is authorised to see
app.get('/users', authenticate, async (req, res, next) => {
  try {
    const users = await db.query('SELECT id, name FROM users'); // no email unless needed
    res.json(users.rows);
  } catch (err) {
    next(err); // centralised error handler — never expose raw errors
  }
});
```

---

### 🟠 4. No Input Validation (High)
**OWASP A03 – Injection**

The app currently has no query-string or body parsing, so any future route additions (filtering by id, search, POST bodies) would be unvalidated by default. This is the gap that enables SQL injection, NoSQL injection, and prototype pollution.

**Fix — add `express-validator` and validate every input point:**
```js
const { query, validationResult } = require('express-validator');

app.get('/users',
  authenticate,
  query('id').optional().isInt({ min: 1 }).toInt(),       // whitelist: integers only
  query('name').optional().isAlphanumeric().trim().escape(), // whitelist: alphanum only
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // safe to use req.query.id / req.query.name now
    next();
  },
  async (req, res, next) => { ... }
);
```

---

### 🟠 5. Missing Security Headers (High)
**OWASP A05 – Security Misconfiguration**

No HTTP security headers are set. This exposes users to clickjacking, MIME sniffing, XSS via reflected content, and information disclosure (`X-Powered-By: Express`).

**Fix — add `helmet`:**
```js
const helmet = require('helmet');

// Must be the FIRST middleware registered
app.use(helmet());
// This sets: Content-Security-Policy, X-Frame-Options, X-Content-Type-Options,
// Strict-Transport-Security, Referrer-Policy, and removes X-Powered-By automatically.
```

---

### 🟡 6. No Rate Limiting (Medium)
**OWASP A04 – Insecure Design**

Without rate limiting, every endpoint is vulnerable to brute-force attacks and denial of service.

**Fix — add `express-rate-limit`:**
```js
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max 100 requests per window per IP
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

app.use(limiter); // apply globally; tighten further on auth routes
```

---

### 🟡 7. No Centralised Error Handler (Medium)
**OWASP A02 – Sensitive Data Exposure**

Without a catch-all error handler, Express's default handler will leak full stack traces (file paths, dependency versions, internal logic) to clients in development — and potentially in misconfigured production deployments.

**Fix — add a safe error handler at the bottom of the middleware stack:**
```js
// Must be registered LAST, after all routes
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';
  console.error(err); // log internally (use a proper logger like pino/winston)
  res.status(err.status || 500).json({
    error: isDev ? err.message : 'An internal error occurred', // never expose stack in prod
  });
});
```

---

### 🟡 8. HTTP Only — No HTTPS Enforcement (Medium)
**OWASP A02 – Sensitive Data Exposure**

`app.listen(3000)` starts a plain HTTP server. Tokens, cookies, and data are transmitted in cleartext.

**Fix — enforce HTTPS and redirect HTTP:**
```js
const https = require('https');
const fs    = require('fs');

const tlsOptions = {
  key:  fs.readFileSync(process.env.TLS_KEY_PATH),
  cert: fs.readFileSync(process.env.TLS_CERT_PATH),
};

https.createServer(tlsOptions, app).listen(443);

// Redirect all HTTP → HTTPS
const http = require('http');
http.createServer((req, res) => {
  res.writeHead(301, { Location: `https://${req.headers.host}${req.url}` });
  res.end();
}).listen(80);
```

---

### 🟡 9. No CORS Policy (Medium)
**OWASP A05 – Security Misconfiguration**

Without explicit CORS headers, the browser's default same-origin policy applies — but once any CORS middleware is added ad-hoc (a common quick-fix), it often becomes `Access-Control-Allow-Origin: *`, which is overly permissive.

**Fix — configure CORS explicitly from the start:**
```js
const cors = require('cors');

const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',');

app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`CORS policy: origin ${origin} not allowed`));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));
```

---

## Complete Hardened `app.js`

Putting it all together:

```js
'use strict';

if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config();
}

const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const jwt       = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');

const app = express();

// ── 1. Security headers (must be first) ────────────────────────────────────
app.use(helmet());

// ── 2. CORS ────────────────────────────────────────────────────────────────
