'use strict';

// ── Environment ────────────────────────────────────────────────────────────
require('dotenv').config();

const PORT       = process.env.PORT       || 3000;
const JWT_SECRET = process.env.JWT_SECRET;

if (!JWT_SECRET) {
  console.error('FATAL: JWT_SECRET environment variable is not set.');
  process.exit(1);
}

// ── Dependencies ───────────────────────────────────────────────────────────
const express    = require('express');
const helmet     = require('helmet');        // security headers
const cors       = require('cors');          // CORS policy
const rateLimit  = require('express-rate-limit');
const jwt        = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');
const winston    = require('winston');

const app = express();

// ── Logger ─────────────────────────────────────────────────────────────────
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'app.log' }),
    new winston.transports.Console({ silent: process.env.NODE_ENV === 'test' }),
  ],
});

// ── Security Middleware ────────────────────────────────────────────────────

// 1. Security headers (removes X-Powered-By, adds CSP, HSTS, etc.)
app.use(helmet());

// 2. CORS — explicit allowlist only
app.use(cors({
  origin: process.env.ALLOWED_ORIGIN || 'https://yourdomain.com',
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  optionsSuccessStatus: 200,
}));

// 3. Body parsing (required before input validation on POST routes)
app.use(express.json({ limit: '10kb' })); // cap body size to prevent DoS

// 4. Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(apiLimiter);

// 5. Request logging
app.use((req, res, next) => {
  logger.info({ method: req.method, url: req.url, ip: req.ip });
  next();
});

// ── Authentication Middleware ──────────────────────────────────────────────
function authenticateToken(req, res, next) {
