/**
 * app.js — Hardened Express Application
 * Security fixes applied per OWASP Top 10 review.
 *
 * Required packages:
 *   npm install helmet cors express-rate-limit express-validator
 */

'use strict';

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// ─── 1. SECURITY HEADERS (OWASP A05) ─────────────────────────────────────────
// Sets X-Frame-Options, X-Content-Type-Options, removes X-Powered-By, etc.
app.use(helmet());

// ─── 2. CORS POLICY (OWASP A05) ──────────────────────────────────────────────
// Explicitly restrict which origins, methods, and headers are permitted.
app.use(cors({
  origin: ['https://yourdomain.com'], // TODO: replace with your actual domain(s)
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// ─── 3. BODY PARSING WITH SIZE LIMIT (OWASP A03) ─────────────────────────────
// Prevents large-payload denial-of-service attacks.
app.use(express.json({ limit: '10kb' }));

// ─── 4. GLOBAL RATE LIMITING (OWASP A07) ─────────────────────────────────────
// Limits each IP to 100 requests per 15-minute window.
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,  // Return RateLimit-* headers (RFC 6585)
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// ─── 5. AUTHENTICATION MIDDLEWARE (OWASP A01, A02) ───────────────────────────
// Replace the stub below with your real token/session validation logic.
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized: missing or malformed token.' });
  }
  const token = authHeader.split(' ')[1];
  if (!isValidToken(token)) {
    return res.status(401).json({ error: 'Unauthorized: invalid token.' });
  }
  next();
}

// TODO: Replace with real JWT verification (e.g., jsonwebtoken.verify())
function isValidToken(token) {
  return typeof token === 'string' && token.length > 0;
}

// ─── IN-MEMORY USER STORE (replace with DB in production) ────────────────────
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ─── ROUTES ───────────────────────────────────────────────────────────────────

// Health check — omits timestamp to avoid leaking server timing info (OWASP A05)
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// List users — requires auth; returns only non-sensitive fields (OWASP A01, A02)
app.get('/users', requireAuth, (req, res) => {
  // Never return raw DB rows. Explicitly select safe fields.
  const safeUsers = users.map(({ id, name }) => ({ id, name }));
  res.json(safeUsers);
});

// Example: Create user — validates and sanitizes all input (OWASP A03)
app.post('/users',
  requireAuth,
  [
    body('name')
      .isString()
      .trim()
      .isLength({ min: 1, max: 100 })
      .escape(),                      // prevents XSS via stored name
    body('email')
      .isEmail()
      .normalizeEmail(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    const { name, email } = req.body;
    const newUser = { id: users.length + 1, name, email };
    users.push(newUser);
    // Return only safe fields in the response
    res.status(201).json({ id: newUser.id, name: newUser.name });
  }
);

// ─── GLOBAL ERROR HANDLER (OWASP A05) ────────────────────────────────────────
// Prevents internal stack traces from leaking to clients.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(err); // Log full error server-side only
  res.status(500).json({ error: 'Internal server error.' });
});

// ─── SERVER ───────────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

