'use strict';

/**
 * app.js — Security-hardened Express application
 *
 * Remediations applied:
 *  - [A02] Sensitive data stripped from API responses
 *  - [A03] Input validation + parameterised query pattern
 *  - [A05] Helmet security headers + body-size limits
 *  - [A07] JWT authentication middleware on protected routes
 *  - [A09] Morgan access logging + safe centralised error handler
 */

const express = require('express');
const helmet  = require('helmet');       // npm install helmet
const morgan  = require('morgan');       // npm install morgan
const jwt     = require('jsonwebtoken'); // npm install jsonwebtoken
const { query, validationResult } = require('express-validator'); // npm install express-validator

const app = express();

// ─── Security Middleware ──────────────────────────────────────────────────────

// Sets X-Frame-Options, X-XSS-Protection, HSTS, noSniff, CSP, etc.
app.use(helmet());

// Structured HTTP access logging
app.use(morgan('combined'));

// Parse JSON bodies with a hard size cap to prevent payload-based DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ─── Authentication Middleware ────────────────────────────────────────────────

/**
 * Validates a Bearer JWT from the Authorization header.
 * Requires JWT_SECRET to be set in the environment — never hard-code secrets.
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Expected: "Bearer <token>"

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    // Fail closed: refuse all requests if the server is misconfigured
    console.error('FATAL: JWT_SECRET environment variable is not set');
    return res.status(500).json({ error: 'Internal server error' });
  }

  jwt.verify(token, secret, { algorithms: ['HS256'] }, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// ─── In-memory data (replace with parameterised DB queries in production) ─────

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
  { id: 2, name: 'Bob',   email: 'bob@example.com',   role: 'admin' },
];

// ─── Routes ───────────────────────────────────────────────────────────────────

// Public health-check — no sensitive data, no auth required
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected route — requires a valid JWT
// A03: query param validated and coerced to integer before use
// A02: email (PII) is stripped from the response for non-admin callers
app.get(
  '/users',
  authenticateToken,
  query('id').optional().isInt({ min: 1 }).toInt(),
  (req, res) => {
    // Reject the request if validation failed
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { id } = req.query;
    const isAdmin = req.user && req.user.role === 'admin';

    // Filter to a specific user when ?id= is supplied
    // NOTE: in a real app, replace this with a parameterised DB query:
    //   db.query('SELECT id, name FROM users WHERE id = ?', [id])
    let result = id
      ? users.filter(u => u.id === id)
      : users;

    // Strip PII — only admins may see email addresses
    result = result.map(({ id, name, email }) =>
      isAdmin ? { id, name, email } : { id, name }
    );

    res.json(result);
  }
);

// ─── Centralised Error Handler ────────────────────────────────────────────────

// Must be registered AFTER all routes (4-argument signature required by Express)
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error internally — never send stack traces to the client
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err.stack);
  res.status(500).json({ error: 'Internal server error' });
});

// ─── Server Bootstrap ─────────────────────────────────────────────────────────

const PORT = parseInt(process.env.PORT, 10) || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

