'use strict';

const express = require('express');
const helmet = require('helmet');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');

const app = express();

// ─── 1. SECURITY HEADERS ────────────────────────────────────────────────────
app.use(helmet());               // Sets CSP, HSTS, X-Frame-Options, etc.
app.disable('x-powered-by');    // Do not advertise the framework

// ─── 2. BODY PARSING (with size limit to prevent DoS) ───────────────────────
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ─── 3. REQUEST LOGGING ─────────────────────────────────────────────────────
app.use(morgan('combined'));     // Log: IP, method, URL, status, response time

// ─── 4. AUTHENTICATION MIDDLEWARE ───────────────────────────────────────────
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header' });
  }

  const token = authHeader.split(' ')[1];

  try {
    // JWT_SECRET must be set in environment — never hardcoded
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// ─── 5. ROUTES ───────────────────────────────────────────────────────────────

// Public health check — no auth required, no sensitive data returned
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected route — requires auth, validates query params, filters PII
app.get(
  '/users',
  requireAuth,
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 }).withMessage('limit must be an integer between 1 and 100')
      .toInt(),
  ],
  (req, res) => {
    // Return 400 if any validation rule failed
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Simulated data — in production, query a DB using parameterized queries
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    // Expose PII (email) only to admins — principle of least privilege
    const safeUsers = allUsers.map(({ id, name, email }) => {
      const record = { id, name };
      if (req.user.role === 'admin') {
        record.email = email;
      }
      return record;
    });

    return res.json(safeUsers);
  }
);

// ─── 6. GLOBAL ERROR HANDLER (must be last) ──────────────────────────────────
// Catches any error passed via next(err) — never leaks stack traces to client
app.use((err, req, res, _next) => {
  console.error(`[${new Date().toISOString()}] Unhandled error: ${err.message}`);
  res.status(err.status || 500).json({ error: 'Internal server error' });
});

// ─── 7. SERVER STARTUP ───────────────────────────────────────────────────────
// PORT and JWT_SECRET must come from environment variables — never hardcoded
const PORT = process.env.PORT || 3000;

if (!process.env.JWT_SECRET) {
  console.error('FATAL: JWT_SECRET environment variable is not set. Exiting.');
  process.exit(1);   // Refuse to start without a secret configured
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

