### 🔴 Finding 1 — Sensitive Data Exposure: User Data Returned Without Authentication
**OWASP A02 / A01** | **Severity: HIGH**

`GET /users` returns PII (names and emails) to **any caller with zero authentication or authorization**. There is no session check, no token validation, and no rate limiting.

**Current code:**
```js
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Fix — add JWT middleware and least-privilege response shaping:**
```js
const jwt = require('jsonwebtoken');

function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Forbidden' });
    req.user = user;
    next();
  });
}

// Only return fields the caller needs; never expose internal IDs to non-admins
app.get('/users', requireAuth, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  // Strip sensitive fields for non-admin callers
  const safeUsers = req.user.role === 'admin'
    ? users
    : users.map(({ name }) => ({ name }));
  res.json(safeUsers);
});
```

